<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserFederatedIdentity\Application\Service\Visibility;

use Psr\EventDispatcher\EventDispatcherInterface;
use Iterator;
use Throwable;
use Civi\Lughauth\Features\Access\User\Application\Service\Visibility\UserVisibilityService;
use Civi\Lughauth\Features\Access\TenantLoginProvider\Application\Service\Visibility\TenantLoginProviderVisibilityService;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\UserFederatedIdentityRef;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\UserFederatedIdentityAttributes;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\UserFederatedIdentity;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\Gateway\UserFederatedIdentityFilter;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\Gateway\UserFederatedIdentityCursor;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\Gateway\UserFederatedIdentityQueryRepositoryGateway;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\Gateway\UserFederatedIdentitySlide;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\Gateway\UserFederatedIdentityCommandRepositoryGateway;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class UserFederatedIdentityVisibilityService
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly UserFederatedIdentityQueryRepositoryGateway $readGateway,
        private readonly UserFederatedIdentityCommandRepositoryGateway $writeGateway,
        private readonly UserVisibilityService $userVisibilityService,
        private readonly TenantLoginProviderVisibilityService $tenantLoginProviderVisibilityService
    ) {
    }

    public function prepareVisibleDataInList(UserFederatedIdentity $content): UserFederatedIdentityAttributes
    {
        return $this->prepareVisibleDataCallback($content, true);
    }
    public function prepareVisibleData(UserFederatedIdentity $content): UserFederatedIdentityAttributes
    {
        return $this->prepareVisibleDataCallback($content, false);
    }
    public function copyWithFixed(UserFederatedIdentityAttributes $attributes, ?UserFederatedIdentity $original = null): UserFederatedIdentityAttributes
    {
        $this->logDebug("Copy with fixed for User federated identity");
        $span = $this->startSpan("Copy with fixed for  User federated identity");
        try {
            $visible = $this->visiblesReferences($attributes);
            $fixed = $this->fieldsToFix($original);
            foreach ($fixed as $field) {
                $visible->unset($field);
            }
            $result = $this->dispatcher->dispatch(new UserFederatedIdentityPresetValues($attributes, $original));
            return $result->attributes;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    public function copyWithHidden(UserFederatedIdentityAttributes $attributes, ?UserFederatedIdentity $original = null): UserFederatedIdentityAttributes
    {
        $this->logDebug("Copy with hidden for User federated identity");
        $span = $this->startSpan("Copy with hidden for  User federated identity");
        try {
            $hidden = $this->fieldsToHide($original);
            foreach ($hidden as $field) {
                $attributes->unset($field);
            }
            return $attributes;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    public function checkVisibility(Iterator|string|UserFederatedIdentityRef $value): bool
    {
        $this->logDebug("Check visibility of an iterator for User federated identity");
        $span = $this->startSpan("Check visibility of an iterator for  User federated identity");
        try {
            if (is_string($value)) {
                return !!$this->retrieveVisibleForUpdate(new UserFederatedIdentityRef($value));
            } elseif ($value instanceof UserFederatedIdentityRef) {
                return !!$this->retrieveVisibleForUpdate($value);
            } elseif ($value instanceof Iterator) {
                $ids = [];
                foreach ($value as $val) {
                    $ids[] = $val->uid();
                }
                $filter = new UserFederatedIdentityFilter(uids: $ids);
                return count($ids) == $this->countVisibles($filter);
            } else {
                return false;
            }
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function listVisibles(UserFederatedIdentityFilter $filter, ?UserFederatedIdentityCursor $cursor = null): UserFederatedIdentitySlide
    {
        $this->logDebug("List visibles for User federated identity");
        $span = $this->startSpan("List visibles for  User federated identity");
        try {
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            $result = $this->readGateway->list($visibleFilter, $cursor);
            return $result->slide(function (UserFederatedIdentity $item): bool {
                return $this->evaluatePostVisibility($item);
            });
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function countVisibles(UserFederatedIdentityFilter $filter): int
    {
        $this->logDebug("Count visibles for User federated identity");
        $span = $this->startSpan("Count visibles for  User federated identity");
        try {
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            return $this->readGateway->count($visibleFilter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function listVisiblesForUpdate(UserFederatedIdentityFilter $filter, ?UserFederatedIdentityCursor $cursor = null): UserFederatedIdentitySlide
    {
        $this->logDebug("List visibles for update for User federated identity");
        $span = $this->startSpan("List visibles for update for  User federated identity");
        try {
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            $result = $this->writeGateway->listForUpdate($visibleFilter, $cursor);
            return $result->slide(function (UserFederatedIdentity $item): bool {
                return $this->evaluatePostVisibility($item);
            });
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function countVisiblesForUpdate(UserFederatedIdentityFilter $filter): int
    {
        $this->logDebug("Count visibles for update for User federated identity");
        $span = $this->startSpan("Count visibles for update for  User federated identity");
        try {
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            return $this->writeGateway->countForUpdate($visibleFilter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function retrieveVisible(UserFederatedIdentityRef $ref): ?UserFederatedIdentity
    {
        $this->logDebug("Retrieve visible for User federated identity");
        $span = $this->startSpan("Retrieve visible for  User federated identity");
        try {
            $filter = new UserFederatedIdentityFilter(uids: [$ref->uid()]);
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            if ($readed = $this->readGateway->retrieve($visibleFilter)) {
                return $this->evaluatePostVisibility($readed) ? $readed : null;
            } else {
                return null;
            }
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function retrieveVisibleForUpdate(UserFederatedIdentityRef $ref): ?UserFederatedIdentity
    {
        $this->logDebug("Retrieve visible for update for User federated identity");
        $span = $this->startSpan("Retrieve visible for update for  User federated identity");
        try {
            $filter = new UserFederatedIdentityFilter(uids: [$ref->uid()]);
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            if ($readed = $this->writeGateway->retrieveForUpdate($visibleFilter)) {
                return $this->evaluatePostVisibility($readed) ? $readed : null;
            } else {
                return null;
            }
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function fieldsToFix(?UserFederatedIdentityRef $ref = null): array
    {
        $this->logDebug("Check fields to fix for User federated identity");
        $span = $this->startSpan("Check fields for fix for User federated identity");
        try {
            $result = $this->dispatcher->dispatch(new UserFederatedIdentityCollectNonEditableFields(UserFederatedIdentity::calculatedFields(), $ref));
            return array_values(array_unique(array_merge($this->fieldsToHide($ref), $result->fields)));
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    public function fieldsToHide(?UserFederatedIdentityRef $ref = null): array
    {
        $this->logDebug("Check fields to hide for User federated identity");
        $span = $this->startSpan("Check fields to hide for  User federated identity");
        try {
            $result = $this->dispatcher->dispatch(new UserFederatedIdentityCollectNonVisibleFields([], $ref));
            return array_values(array_unique($result->fields));
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    private function visiblesReferences(UserFederatedIdentityAttributes $attributes): UserFederatedIdentityAttributes
    {
        $this->logDebug("Check visibility of parent references for User federated identity");
        $span = $this->startSpan("Check visibility of parent references for  User federated identity");
        try {
            $user = $attributes->getUser();
            if (null !== $user && !$this->userVisibilityService->checkVisibility($user)) {
                throw new NotFoundException("Unknown User " . ($user->uid() ?? 'no-id'));
            }
            $loginProvider = $attributes->getLoginProvider();
            if (null !== $loginProvider && !$this->tenantLoginProviderVisibilityService->checkVisibility($loginProvider)) {
                throw new NotFoundException("Unknown LoginProvider " . ($loginProvider->uid() ?? 'no-id'));
            }
            return $attributes;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function applyPreVisibilityFilter(UserFederatedIdentityFilter $filter): UserFederatedIdentityFilter
    {
        $this->logDebug("Compose visibility filter for User federated identity");
        $span = $this->startSpan("Compose visibility filter for  User federated identity");
        try {
            $result = $this->dispatcher->dispatch(new UserFederatedIdentityRestrictFilterToVisibility($filter));
            return $result->userFederatedIdentityFilter;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function evaluatePostVisibility(UserFederatedIdentity $value): bool
    {
        $this->logDebug("Check if item is visible for User federated identity");
        $span = $this->startSpan("Check if item is visible for  User federated identity");
        try {
            $result = $this->dispatcher->dispatch(new UserFederatedIdentityVisibilityCheck(true, $value));
            return $result->visible;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function prepareVisibleDataCallback(UserFederatedIdentity $content, bool $inlist): UserFederatedIdentityAttributes
    {
        $this->logDebug("Prepare hydration to visible data for User federated identity");
        $span = $this->startSpan("Prepare hydration to visible data for User federated identity");
        try {
            $attributes = $content->toAttributes();
            $result = $this->dispatcher->dispatch(new UserFederatedIdentityEnrichForView($content, $inlist, $attributes));
            return $result->getEnrichedAttributes();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
